def test_parameter_decorator_reusable(runner):
    """A custom class can be used when a parameter decorator is reused
    on multiple commands. See Issue #926.
    """

    class CustomArgument(click.Argument):
        pass

    class CustomOption(click.Option):
        pass

    argument = click.argument("name", cls=CustomArgument)
    option = click.option("--name", cls=CustomOption)

    @click.command()
    @argument
    @option
    def first(name):
        click.echo(f"first:{name}")

    @click.command()
    @argument
    @option
    def second(name):
        click.echo(f"second:{name}")

    for command in (first, second):
        assert type(command.params[0]) is CustomArgument
        assert type(command.params[1]) is CustomOption

    assert first.params[0] is not second.params[0]
    assert first.params[1] is not second.params[1]

    result = runner.invoke(first, ["--name", "a", "b"])
    assert result.output == "first:b\n"
    result = runner.invoke(second, ["--name", "c", "d"])
    assert result.output == "second:d\n"
